macro_rules! FlushCompress {
    () => {
        # [doc = " Values which indicate the form of flushing to be used when compressing"] # [doc = " in-memory data."] # [derive (Copy , Clone , PartialEq , Eq , Debug)] # [non_exhaustive] # [allow (clippy :: unnecessary_cast)] pub enum FlushCompress { # [doc = " A typical parameter for passing to compression/decompression functions,"] # [doc = " this indicates that the underlying stream to decide how much data to"] # [doc = " accumulate before producing output in order to maximize compression."] None = libz_rs_sys :: Z_NO_FLUSH as isize , # [doc = " All pending output is flushed to the output buffer, but the output is"] # [doc = " not aligned to a byte boundary."] # [doc = ""] # [doc = " All input data so far will be available to the decompressor (as with"] # [doc = " `Flush::Sync`). This completes the current deflate block and follows it"] # [doc = " with an empty fixed codes block that is 10 bits long, and it assures"] # [doc = " that enough bytes are output in order for the decompressor to finish the"] # [doc = " block before the empty fixed code block."] Partial = libz_rs_sys :: Z_PARTIAL_FLUSH as isize , # [doc = " All pending output is flushed to the output buffer and the output is"] # [doc = " aligned on a byte boundary so that the decompressor can get all input"] # [doc = " data available so far."] # [doc = ""] # [doc = " Flushing may degrade compression for some compression algorithms and so"] # [doc = " it should only be used when necessary. This will complete the current"] # [doc = " deflate block and follow it with an empty stored block."] Sync = libz_rs_sys :: Z_SYNC_FLUSH as isize , # [doc = " All output is flushed as with `Flush::Sync` and the compression state is"] # [doc = " reset so decompression can restart from this point if previous"] # [doc = " compressed data has been damaged or if random access is desired."] # [doc = ""] # [doc = " Using this option too often can seriously degrade compression."] Full = libz_rs_sys :: Z_FULL_FLUSH as isize , # [doc = " Pending input is processed and pending output is flushed."] # [doc = ""] # [doc = " The return value may indicate that the stream is not yet done and more"] # [doc = " data has yet to be processed."] Finish = libz_rs_sys :: Z_FINISH as isize , }
    };
}

FlushCompress!();